//! Stored datasets and stages for ingestion runs.

use std::time::SystemTime;

use super::entity_ingestion::IngestionKey;

/// Dataset stored by an ingestion run.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub enum IngestionDataset {
    /// Parliamentary members.
    Members,
    /// Members' declarations.
    Declarations,
}

/// Stored data stages, ordered by progress through the pipeline.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub enum IngestionDataStage {
    /// Source data from Parliament.
    Raw,
    /// Cleaned source data.
    Cleaned,
    /// Data with resolved entities.
    Resolved,
}

/// Evidence of a stored dataset at one stage of an ingestion run.
#[derive(Clone, Debug)]
pub struct StoredIngestionDataset {
    /// Run that contains the dataset.
    pub key: IngestionKey,
    /// Kind of data stored.
    pub dataset: IngestionDataset,
    /// Stage of the stored data.
    pub stage: IngestionDataStage,
    /// Most recent modification time of the dataset's files.
    pub modified_at: SystemTime,
}

/// Available datasets in the latest ingestion run.
#[derive(Debug, PartialEq, Eq)]
pub struct IngestionStatus {
    /// Key shared by the reported datasets.
    pub key: IngestionKey,
    /// Furthest stored stage for each available dataset, in dataset order.
    pub datasets: Vec<(IngestionDataset, IngestionDataStage)>,
}
//! Inspect the latest ingestion run through its stored datasets.

use std::collections::BTreeMap;

use crate::domain::{
    models::{entity_ingestion::EntityIngestionError, ingestion_status::IngestionStatus},
    repositories::ingestion_catalog::IngestionCatalog,
};

#[cfg(test)]
mod tests;

/// Reports available datasets without changes to ingestion storage.
pub struct IngestionStatusService<C> {
    catalog: C,
}

impl<C: IngestionCatalog> IngestionStatusService<C> {
    /// Creates a service with the supplied catalog.
    pub const fn new(catalog: C) -> Self {
        Self { catalog }
    }

    /// Returns the run with the most recently modified dataset file.
    /// Equal timestamps use the greatest UUID as a deterministic tie-breaker.
    /// Each dataset reports its furthest stored stage within that run.
    /// Returns `None` if no stored datasets exist.
    ///
    /// # Errors
    /// Returns an error if the catalog cannot read ingestion storage.
    pub async fn latest(&self) -> Result<Option<IngestionStatus>, EntityIngestionError> {
        let stored = self.catalog.stored_datasets().await?;
        let Some(latest) = stored
            .iter()
            .max_by_key(|entry| (entry.modified_at, entry.key.uuid()))
        else {
            return Ok(None);
        };
        let key = latest.key.clone();
        let mut datasets = BTreeMap::new();
        for entry in stored.into_iter().filter(|entry| entry.key == key) {
            datasets
                .entry(entry.dataset)
                .and_modify(|stage| *stage = entry.stage.max(*stage))
                .or_insert(entry.stage);
        }
        Ok(Some(IngestionStatus {
            key,
            datasets: datasets.into_iter().collect(),
        }))
    }
}
use std::{
    future::ready,
    time::{Duration, SystemTime},
};

use uuid::Uuid;

use super::*;
use crate::domain::{
    models::{
        entity_ingestion::IngestionKey,
        ingestion_status::{IngestionDataStage, IngestionDataset, StoredIngestionDataset},
    },
    repositories::entity_ingestion::EntitySearchPipelineError,
};

struct Catalog(Vec<StoredIngestionDataset>);

impl IngestionCatalog for Catalog {
    fn stored_datasets(
        &self,
    ) -> impl Future<Output = Result<Vec<StoredIngestionDataset>, EntitySearchPipelineError>> + Send
    {
        ready(Ok(self.0.clone()))
    }
}

fn stored(
    key: u128,
    dataset: IngestionDataset,
    stage: IngestionDataStage,
    seconds: u64,
) -> StoredIngestionDataset {
    StoredIngestionDataset {
        key: IngestionKey::new(Uuid::from_u128(key)),
        dataset,
        stage,
        modified_at: SystemTime::UNIX_EPOCH + Duration::from_secs(seconds),
    }
}

#[tokio::test]
async fn latest_uses_file_time_and_reports_furthest_stages_only_within_that_run()
-> anyhow::Result<()> {
    use IngestionDataStage::{Cleaned, Raw, Resolved};
    use IngestionDataset::{Declarations, Members};

    let service = IngestionStatusService::new(Catalog(vec![
        stored(99, Members, Resolved, 10),
        stored(1, Declarations, Cleaned, 20),
        stored(1, Members, Resolved, 15),
        stored(1, Declarations, Raw, 30),
        stored(1, Members, Raw, 14),
    ]));

    assert_eq!(
        service.latest().await?,
        Some(IngestionStatus {
            key: IngestionKey::new(Uuid::from_u128(1)),
            datasets: vec![(Members, Resolved), (Declarations, Cleaned)],
        })
    );
    Ok(())
}

#[tokio::test]
async fn equal_timestamps_choose_the_same_run_regardless_of_catalog_order() -> anyhow::Result<()> {
    let datasets = vec![
        stored(1, IngestionDataset::Members, IngestionDataStage::Raw, 10),
        stored(
            2,
            IngestionDataset::Declarations,
            IngestionDataStage::Raw,
            10,
        ),
    ];
    let forward = IngestionStatusService::new(Catalog(datasets.clone()))
        .latest()
        .await?;
    let reverse = IngestionStatusService::new(Catalog(datasets.into_iter().rev().collect()))
        .latest()
        .await?;

    assert_eq!(forward, reverse);
    assert_eq!(forward.unwrap().key, IngestionKey::new(Uuid::from_u128(2)));
    Ok(())
}

#[tokio::test]
async fn empty_catalog_has_no_latest_run() -> anyhow::Result<()> {
    assert_eq!(
        IngestionStatusService::new(Catalog(vec![]))
            .latest()
            .await?,
        None
    );
    Ok(())
}

#[tokio::test]
async fn read_failure_is_not_reported_as_an_empty_catalog() {
    struct UnreadableCatalog;
    impl IngestionCatalog for UnreadableCatalog {
        fn stored_datasets(
            &self,
        ) -> impl Future<Output = Result<Vec<StoredIngestionDataset>, EntitySearchPipelineError>> + Send
        {
            ready(Err(EntitySearchPipelineError::ReadError(
                "permission denied".into(),
            )))
        }
    }

    assert!(matches!(
        IngestionStatusService::new(UnreadableCatalog).latest().await,
        Err(EntityIngestionError::IoError(EntitySearchPipelineError::ReadError(message))) if message == "permission denied"
    ));
}
//! CLI coverage for read-only ingestion status.

use std::{
    fs,
    path::Path,
    process::{Command, Output},
    time::{Duration, SystemTime},
};

use exposed::{
    domain::{
        models::{declaration_ingestion::MemberAsId, entity_ingestion::IngestionKey},
        repositories::entity_ingestion::EntityIngestionStorage,
    },
    outbound::ExposedDataPipeline,
};
use tempfile::TempDir;
use uuid::Uuid;

fn run_latest(root: &Path) -> anyhow::Result<Output> {
    fs::write(root.join(".env"), "")?;
    // Existing fetch configuration works. Only data_dir is required.
    fs::write(
        root.join("config.yaml"),
        "data_dir: ./data\nbatch_size: 100\n",
    )?;
    Ok(Command::new(env!("CARGO_BIN_EXE_exposed"))
        .current_dir(root)
        .env_remove("DATABASE_URL")
        .args(["data", "latest", "config.yaml"])
        .output()?)
}

fn stdout(output: &Output) -> &str {
    assert!(
        output.status.success(),
        "{}",
        String::from_utf8_lossy(&output.stderr)
    );
    std::str::from_utf8(&output.stdout).unwrap()
}

fn set_modified(path: &Path, seconds: u64) -> anyhow::Result<()> {
    fs::File::open(path)?.set_modified(SystemTime::UNIX_EPOCH + Duration::from_secs(seconds))?;
    Ok(())
}

#[tokio::test]
async fn reports_both_datasets_written_by_the_pipeline_without_a_database() -> anyhow::Result<()> {
    let tmp = TempDir::new()?;
    let key = IngestionKey::default();
    let pipeline =
        ExposedDataPipeline::new_with_ingestion_key(&tmp.path().join("data"), key.clone())?;
    pipeline.write_raw_members(&[]).await?;
    pipeline
        .write_raw_declarations(MemberAsId::new(Uuid::from_u128(42), 512)?, &[])
        .await?;

    let output = run_latest(tmp.path())?;

    assert_eq!(
        stdout(&output),
        format!("Ingestion key: {key}\nDATASET\tSTAGE\nmembers\traw\ndeclarations\traw\n")
    );
    assert_eq!(fs::read_dir(tmp.path().join("data"))?.count(), 1);
    Ok(())
}

#[tokio::test]
async fn uses_nested_file_timestamps_and_does_not_mix_separate_runs() -> anyhow::Result<()> {
    let tmp = TempDir::new()?;
    // UUIDv4 keys need not sort in the same order as dataset timestamps.
    let older: IngestionKey = "ffffffff-ffff-4fff-8fff-ffffffffffff".parse()?;
    let latest: IngestionKey = "00000000-0000-4000-8000-000000000001".parse()?;
    let data = tmp.path().join("data");
    let members = ExposedDataPipeline::new_with_ingestion_key(&data, older.clone())?;
    members.write_raw_members(&[]).await?;
    set_modified(
        &data.join(older.to_string()).join("raw/members.parquet"),
        10,
    )?;
    let declarations = ExposedDataPipeline::new_with_ingestion_key(&data, latest.clone())?;
    let member = MemberAsId::new(Uuid::from_u128(42), 512)?;
    declarations.write_raw_declarations(member, &[]).await?;
    set_modified(
        &data
            .join(latest.to_string())
            .join(format!("raw/declarations/{}.parquet", member.member_id())),
        20,
    )?;
    // Directory timestamps do not determine the latest dataset.
    set_modified(&data.join(latest.to_string()), 1)?;
    fs::create_dir_all(
        data.join(IngestionKey::default().to_string())
            .join("raw/declarations"),
    )?;

    let output = run_latest(tmp.path())?;

    assert_eq!(
        stdout(&output),
        format!("Ingestion key: {latest}\nDATASET\tSTAGE\ndeclarations\traw\n")
    );
    Ok(())
}

#[tokio::test]
async fn reports_the_furthest_stored_stage_for_each_dataset() -> anyhow::Result<()> {
    let tmp = TempDir::new()?;
    let key = IngestionKey::default();
    let data = tmp.path().join("data");
    let pipeline = ExposedDataPipeline::new_with_ingestion_key(&data, key.clone())?;
    pipeline.write_raw_members(&[]).await?;
    let member = MemberAsId::new(Uuid::from_u128(42), 512)?;
    pipeline.write_raw_declarations(member, &[]).await?;
    let run = data.join(key.to_string());
    fs::create_dir_all(run.join("resolved"))?;
    fs::copy(
        run.join("raw/members.parquet"),
        run.join("resolved/members.parquet"),
    )?;
    fs::create_dir_all(run.join("cleaned/declarations"))?;
    let partition = format!("declarations/{}.parquet", member.member_id());
    fs::copy(
        run.join("raw").join(&partition),
        run.join("cleaned").join(&partition),
    )?;

    let output = run_latest(tmp.path())?;

    assert_eq!(
        stdout(&output),
        format!("Ingestion key: {key}\nDATASET\tSTAGE\nmembers\tresolved\ndeclarations\tcleaned\n")
    );
    Ok(())
}

#[test]
fn missing_store_stays_absent() -> anyhow::Result<()> {
    let tmp = TempDir::new()?;
    fs::write(tmp.path().join(".env"), "")?;
    fs::write(tmp.path().join("config.yaml"), "data_dir: ./data\n")?;
    let output = Command::new(env!("CARGO_BIN_EXE_exposed"))
        .current_dir(tmp.path())
        .env_remove("DATABASE_URL")
        .args(["data", "latest", "config.yaml"])
        .output()?;

    assert_eq!(stdout(&output), "No ingestion datasets found.\n");
    assert!(!tmp.path().join("data").exists());
    Ok(())
}

#[test]
fn ignores_empty_runs_unrelated_files_and_invalid_keys() -> anyhow::Result<()> {
    let tmp = TempDir::new()?;
    let data = tmp.path().join("data");
    let run = data.join(IngestionKey::default().to_string());
    fs::create_dir_all(run.join("raw/declarations"))?;
    fs::write(run.join("raw/declarations/notes.txt"), "not a dataset")?;
    fs::create_dir_all(run.join("raw/members.parquet"))?;
    fs::create_dir_all(data.join("not-an-ingestion-key/raw"))?;
    fs::write(
        data.join("not-an-ingestion-key/raw/members.parquet"),
        "ignored",
    )?;
    fs::write(
        data.join(IngestionKey::default().to_string()),
        "not a directory",
    )?;

    let output = run_latest(tmp.path())?;

    assert_eq!(stdout(&output), "No ingestion datasets found.\n");
    Ok(())
}

#[test]
fn invalid_store_path_fails_with_a_read_error() -> anyhow::Result<()> {
    let tmp = TempDir::new()?;
    fs::write(tmp.path().join("data"), "not a directory")?;

    let output = run_latest(tmp.path())?;

    assert!(!output.status.success());
    assert!(output.stdout.is_empty());
    assert!(String::from_utf8_lossy(&output.stderr).contains("unable to read pipeline data"));
    Ok(())
}
# Architecture overview

Diagrams exist for this project `exposed architecture` excalidraw board. 

The `data latest` CLI command constructs `IngestionStatusService` with the
filesystem adapter `ExposedIngestionCatalog`. The service selects the latest run
and each dataset's furthest stage through the domain-owned `IngestionCatalog`
port. The adapter reads file names and modification times. The CLI formats the
result, and the command does not change stored data.
```sh
test -f .env || cp .env.example .env
cargo run --package exposed --bin exposed -- server
```

Edit `DATABASE_URL` in `.env` to use another database. Git ignores `.env`.

The `data members load` and `data declarations fetch` commands also read
`DATABASE_URL` from the environment or `.env`, with the same precedence as the server.
Their YAML files contain only data settings such as `data_dir` and `batch_size`.
Remove `connection_string` from existing YAML files and set `DATABASE_URL` in `.env` instead.
The `data members fetch` command does not require a database URL.

To fetch and load members, use the same ingestion key for both stages:

```sh
test -f .env || cp .env.example .env
ingestion_key=$(uuidgen)
cargo run --package exposed --bin exposed -- data members fetch exposed/config/cli-dev.yaml --ingestion-key "$ingestion_key"
cargo run --package exposed --bin exposed -- data members load exposed/config/cli-dev.yaml --ingestion-key "$ingestion_key"
cargo run --package exposed --bin exposed -- data declarations fetch exposed/config/declarations-dev.yaml
```

To inspect the latest stored ingestion run, use either fetch configuration:

```sh
cargo run --package exposed --bin exposed -- data latest exposed/config/cli-dev.yaml
```

The command prints the ingestion key and each available dataset (`members` or
`declarations`), with its furthest stored stage (`raw`, `cleaned`, or `resolved`).
It selects the run with the most recently modified dataset file. Equal timestamps
use the greatest UUID. Keys must be UUIDs. Empty directories do not count as datasets.
The command reports only datasets from the selected run.

This command requires only `data_dir` in the YAML file and no database connection
at runtime. It does not change files. An absent or empty data directory produces
`No ingestion datasets found.` and a successful exit. File presence indicates the
stored stage. It does not confirm a complete fetch or a database load.

The frontend service proxies `/api/search` to `http://exposed:6999/search`.
Its source is bind-mounted, with polling for live reload on Docker Desktop and a
separate Linux dependency volume. Restart `frontend` after changing its package
manifest or lockfile; dependencies are refreshed at startup. The API may take
longer than the frontend to compile on a first run; use **Try again** if search
is not ready yet.

Use `docker compose stop frontend exposed` to stop the app and keep the caches.
`make db-start` and `make db-stop` control only PostgreSQL.

The Compose project is named `exposed`. When testing a frontend-only change in a
worktree against an already running API, use
`docker compose up --build -d --no-deps frontend` to avoid recreating the backend
and database from that worktree. This serves the frontend from the worktree.

### Frontend development and checks

To run the frontend on the host instead of Docker, use Node.js **24+**:

```sh
cd frontend
npm ci
npm run dev
```

The host dev server proxies to `http://127.0.0.1:6999` by default. Override
`EXPOSED_API_ORIGIN` when starting Vite to use another backend. This setting is
server-side; the browser always uses the same-origin `/api/search` path.
The frontend image is for local development. `npm run build` produces static
assets in `frontend/dist`; a production host must also route `/api/search` to
the Rust API.

