//! File system interface for entity search ingestion

use std::{
    io::ErrorKind,
    path::{self, Path, PathBuf},
    time::SystemTime,
};

use arrow::datatypes::{DataType, Field, Schema};
use tokio::fs;
use uuid::Uuid;

use crate::domain::{
    models::{
        entity_ingestion::IngestionKey,
        ingestion_status::{IngestionDataStage, IngestionDataset, IngestionStatus},
    },
    repositories::entity_ingestion::EntitySearchPipelineError,
};

/// File system pipeline
#[derive(Clone)]
pub struct ExposedDataPipeline {
    root: PathBuf,
    key: PipelineKey,
    fs_schema: FsSchema,
}

#[derive(Clone)]
pub struct PipelineKey(Uuid);

impl PipelineKey {
    pub fn new() -> Self {
        Self(Uuid::now_v7())
    }
}

impl From<&PipelineKey> for IngestionKey {
    fn from(value: &PipelineKey) -> Self {
        Self::new(value.0)
    }
}

impl From<IngestionKey> for PipelineKey {
    fn from(value: IngestionKey) -> Self {
        Self(value.uuid())
    }
}

#[derive(Clone)]
struct FsSchema {
    raw: String,
    // cleaned: String,
    // resolved: String,
}

impl Default for FsSchema {
    fn default() -> Self {
        Self {
            raw: "raw".into(),
            // cleaned: "cleaned".into(),
            // resolved: "resolved".into(),
        }
    }
}

impl ExposedDataPipeline {
    /// Returns the run with the most recently modified dataset file.
    /// Equal timestamps use the greatest UUID. Each dataset reports its furthest stored stage.
    /// Empty directories do not count as datasets. An absent store returns `None`.
    /// This operation does not create or change files.
    ///
    /// # Errors
    /// Returns an error if ingestion storage cannot be read.
    pub async fn latest_ingestion(
        root: &Path,
    ) -> Result<Option<IngestionStatus>, EntitySearchPipelineError> {
        let mut entries = match fs::read_dir(root).await {
            Ok(entries) => entries,
            Err(error) if error.kind() == ErrorKind::NotFound => return Ok(None),
            Err(error) => return Err(read_error(root, error)),
        };
        let schema = FsSchema::default();
        let mut latest: Option<(SystemTime, IngestionStatus)> = None;
        while let Some(entry) = entries
            .next_entry()
            .await
            .map_err(|e| read_error(root, e))?
        {
            let path = entry.path();
            if !entry
                .file_type()
                .await
                .map_err(|e| read_error(&path, e))?
                .is_dir()
            {
                continue;
            }
            let Some(key) = entry
                .file_name()
                .to_str()
                .and_then(|name| name.parse::<IngestionKey>().ok())
            else {
                continue;
            };
            let mut modified_at = None;
            let mut datasets = Vec::new();
            for dataset in [IngestionDataset::Members, IngestionDataset::Declarations] {
                let mut furthest_stage = None;
                for (stage, directory) in [
                    (IngestionDataStage::Raw, schema.raw.as_str()),
                    (IngestionDataStage::Cleaned, "cleaned"),
                    (IngestionDataStage::Resolved, "resolved"),
                ] {
                    let stage_path = path.join(directory);
                    let dataset_modified_at = match dataset {
                        IngestionDataset::Members => {
                            file_modified_at(&stage_path.join("members.parquet")).await?
                        }
                        IngestionDataset::Declarations => {
                            declarations_modified_at(&stage_path.join("declarations")).await?
                        }
                    };
                    if let Some(dataset_modified_at) = dataset_modified_at {
                        modified_at = modified_at.max(Some(dataset_modified_at));
                        furthest_stage = furthest_stage.max(Some(stage));
                    }
                }
                if let Some(stage) = furthest_stage {
                    datasets.push((dataset, stage));
                }
            }
            let Some(modified_at) = modified_at else {
                continue;
            };
            if latest.as_ref().is_none_or(|(latest_time, status)| {
                (modified_at, key.uuid()) > (*latest_time, status.key.uuid())
            }) {
                latest = Some((modified_at, IngestionStatus { key, datasets }));
            }
        }
        Ok(latest.map(|(_, status)| status))
    }

    /// Creates a new instance of [`ExposedDataPipeline`] with an [`IngestionKey`]
    ///
    /// # Errors
    /// - if [`root`] cannot be parsed as absolute
    /// - if required directories cannot be created
    pub fn new_with_ingestion_key(
        root: &PathBuf,
        key: IngestionKey,
    ) -> Result<Self, EntitySearchPipelineError> {
        let root_abs = path::absolute(root).map_err(|_| {
            EntitySearchPipelineError::Unexpected("valid root path must be provided".to_string())
        })?;

        let res = Self {
            root: root_abs,
            key: PipelineKey::from(key),
            fs_schema: FsSchema::default(),
        };
        std::fs::create_dir_all(res.raw_path()).map_err(|_| {
            EntitySearchPipelineError::Unexpected("must be able to create fs paths".to_string())
        })?;
        Ok(res)
    }

    fn latest_run_path(&self) -> PathBuf {
        self.root.join(self.key.0.to_string())
    }

    pub(super) fn raw_path(&self) -> PathBuf {
        self.latest_run_path().join(&self.fs_schema.raw)
    }

    pub(super) const fn key(&self) -> &PipelineKey {
        &self.key
    }

    // pub(super) fn cleaned_path(&self) -> PathBuf {
    //     self.latest_run_path().join(&self.fs_schema.cleaned)
    // }
    //
    // pub(super) fn resolved_path(&self) -> PathBuf {
    //     self.latest_run_path().join(&self.fs_schema.resolved)
    // }
}

async fn file_modified_at(path: &Path) -> Result<Option<SystemTime>, EntitySearchPipelineError> {
    match fs::symlink_metadata(path).await {
        Ok(metadata) if metadata.is_file() => metadata
            .modified()
            .map(Some)
            .map_err(|e| read_error(path, e)),
        Ok(_) => Ok(None),
        Err(error) if error.kind() == ErrorKind::NotFound => Ok(None),
        Err(error) => Err(read_error(path, error)),
    }
}

async fn declarations_modified_at(
    path: &Path,
) -> Result<Option<SystemTime>, EntitySearchPipelineError> {
    let mut entries = match fs::read_dir(path).await {
        Ok(entries) => entries,
        Err(error) if error.kind() == ErrorKind::NotFound => return Ok(None),
        Err(error) => return Err(read_error(path, error)),
    };
    let mut latest = None;
    while let Some(entry) = entries
        .next_entry()
        .await
        .map_err(|e| read_error(path, e))?
    {
        let file_path = entry.path();
        if file_path
            .extension()
            .is_some_and(|extension| extension == "parquet")
        {
            latest = latest.max(file_modified_at(&file_path).await?);
        }
    }
    Ok(latest)
}

fn read_error(path: &Path, error: impl std::fmt::Display) -> EntitySearchPipelineError {
    EntitySearchPipelineError::ReadError(format!("{}: {error}", path.display()))
}

pub(super) fn members_schema() -> Schema {
    let pmi = Field::new("parliament_member_id", DataType::UInt32, false);
    let n = Field::new("name", DataType::Utf8, false);
    let pi = Field::new("party_id", DataType::UInt32, false);
    let pn = Field::new("party_name", DataType::Utf8, false);
    let c = Field::new("constituency", DataType::Utf8, false);
    Schema::new(vec![pmi, n, pi, pn, c])
}
